export default function createNode(config, ctx) {
  const group = new Group();

  // --- Geometry ---
  const geometry = new PlaneGeometry(1.2, 0.75, 64, 64);

  // --- Textures ---
  let colorTexture = null;
  let depthTexture = null;

  const texturePromises = [];

  if (config.imageUrl) {
    texturePromises.push(
      ctx.textureLoader.loadTexture(config.imageUrl).then(tex => {
        colorTexture = tex;
        tex.colorSpace = 'srgb';
      })
