      ctx.textureLoader.loadTexture(config.depthMapUrl).then(tex => {
        depthTexture = tex;
      })
    );
  }

  // --- Colors from spec ---
  const colors = {
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
    accent: new Color('#ff2a38'),
    surface: new Color('#0b0b10')
  };

  // --- Displacement material with TSL ---
  const displaceStrength = uniform(0.04);
  const parallaxOffset = uniform(new Vector2(0, 0));
  const hoverLift = uniform(0);

  const displacementMap = depthTexture ? texture(depthTexture) : null;

  const material = new MeshPhysicalNodeMaterial();
  material.roughness = 0.6;
  material.metalness = 0.45;
  material.clearcoat = 0.15;
  material.color = colors.surface.clone();

  if (colorTexture) {
    material.map = colorTexture;
  }

  // Displacement node
  const displacementNode = Fn(() => {
    if (!displacementMap) return vec3(0);

    const depth = displacementMap.sample(uv()).r;
    const offset = depth.mul(displaceStrength);

    // Add parallax offset to UV for position
    const parallaxUv = uv().add(parallaxOffset.mul(0.02));
    const parallaxDepth = displacementMap.sample(parallaxUv).r;
    const parallaxOffset3 = parallaxDepth.sub(depth).mul(displaceStrength.mul(0.5));

    const totalOffset = offset.add(parallaxOffset3);

    return normalLocal.mul(totalOffset);
  });

  material.positionNode = displacementNode;

  // Edge accent glow
  const edgeGlow = uniform(0);
  const accentColor = colors.accent.clone();

  material.emissiveNode = Fn(() => {
    const glow = edgeGlow.mul(0.15);
    return vec3(accentColor.r, accentColor.g, accentColor.b).mul(glow);
  })();

  // --- Mesh ---
  const mesh = new Mesh(geometry, material);
  mesh.position.z = 0;
  group.add(mesh);

