  const handlers = {};

  handlers.onPointerEnter = () => {
    gsap.to(mesh.position, { y: 0.15, duration: 0.5, ease: 'power2.out' });
    gsap.to(material, { emissiveIntensity: 1.2, duration: 0.3, ease: 'power1.out' });
    gsap.to(edgeGlove, { value: 1, duration: 0.3, ease: 'power1.out' });
