  handlers.onPointerLeave = () => {
    gsap.to(mesh.position, { y: 0, duration: 0.5, ease: 'power2.out' });
    gsap.to(material, { emissiveIntensity: 0, duration: 0.4, ease: 'power2.out' });
    gsap.to(edgeGlove, { value: 0, duration: 0.4, ease: 'power2.out' });
  };

