    gsap.to(mesh.scale, { x: 1, y: 1, duration: 0.4, ease: 'power2.out' });
    gsap.to(shadow.scale, { x: 1, y: 1, duration: 0.4, ease: 'power2.out' });

    if (handlers._clickEmit) {
      ctx.emit('hub-features.select', {});
    }
  };

  handlers._clickEmit = true;

  // --- Parallax tracking ---
  const parallaxTarget = new Vector2(0, 0);
  const parallaxCurrent = new Vector2(0, 0);

  handlers.onPointerMove = (event) => {
    const v = new Vector2(
      (event.clientX / window.innerWidth - 0.5) * 2,
      -(event.clientY / window.innerHeight - 0.5) * 2
    );
    parallaxTarget.copy(v);
  };

  // Animate parallax
  const parallaxLoop = () => {
    parallaxCurrent.lerp(parallaxTarget, 0.05);
    parallaxOffset.value.copy(parallaxCurrent);

    if (handlers._running) {
      requestAnimationFrame(parallaxLoop);
    }
  };
